import { memo, useMemo } from 'react';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { useUpdateDefaultWalletMutation } from '~/entities/wallet/api/use-update-default-wallet-mutation';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';

type PaymentProps = {
  openQRScanner: (options: { scannerType: ScannerType }) => void;
};

export const Payment = memo(function Payment({ openQRScanner }: PaymentProps) {
  const { navigate } = useNavigate();
  const { data: walletList = [] } = useGetCstmrWalletListQuery();
  const { data: userRes } = useGetUserInfoQuery();
  const isPriWalletDefault = userRes?.tbCstmrMastr?.priAliasNm === userRes?.tbCstmrMastr?.dfltAliasNm;
  const priAliasNm = userRes?.tbCstmrMastr?.priAliasNm;
  const dfltAliasNm = userRes?.tbCstmrMastr?.dfltAliasNm;

  const { mutateAsync: updateDefaultWallet } = useUpdateDefaultWalletMutation();

  const primaryWalletTokenList = useMemo(() => {
    const primaryWallet = walletList.find((wallet) => wallet.priAliasNm === wallet.aliasNm) ?? walletList[0];
    return primaryWallet?.tokenList ?? [];
  }, [walletList]);

  const handleShowPaymentQRCode = async () => {
    if (!isPriWalletDefault) {
      const paramAliasNm = priAliasNm ?? dfltAliasNm!;
      await updateDefaultWallet(paramAliasNm);
    }
    closeDialog(() =>
      navigate(PATHS.payment.myPaymentQRCode, {
        state: { tokenList: primaryWalletTokenList },
      }),
    );
  };

  const handleQrScan = async () => {
    if (!isPriWalletDefault) {
      const paramAliasNm = priAliasNm ?? dfltAliasNm!;
      await updateDefaultWallet(paramAliasNm);
    }
    closeDialog(() =>
      openQRScanner({
        scannerType: ScannerType.PaymentQRScan,
      }),
    );
  };

  return (
    <section className="main-qrshop-container">
      <button type="button" className="btn-main-link-wrapper" aria-label="QR스캔하기" onClick={handleQrScan}>
        <span className="main-link-title">
          QR
          <br />
          스캔하기
        </span>
        <i className="icon-main-link-qrscan"></i>
      </button>
      <button
        type="button"
        className="btn-main-link-wrapper"
        aria-label="QR보여주기"
        onClick={handleShowPaymentQRCode}
      >
        <span className="main-link-title">
          QR
          <br />
          보여주기
        </span>
        <i className="icon-main-link-qrshow"></i>
      </button>
      <button
        type="button"
        className="btn-main-link-wrapper"
        aria-label="사용처 찾아보기"
        onClick={() => navigate(PATHS.shopList)}
      >
        <span className="main-link-title">
          사용처
          <br />
          찾아보기
        </span>
        <i className="icon-main-link-qrshop"></i>
      </button>
    </section>
  );
});
