import clsx from 'clsx';
import { memo, useCallback, useMemo, MouseEvent } from 'react';
import { useStore } from '~/app/store/store';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { WalletStatus } from '~/entities/home/ui/wallet/wallet-status';
import { useNotificationListInfiniteQuery } from '~/entities/notification/api/use-notification-list-infinite-query';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { sortWalletsForDisplay } from '~/entities/wallet/lib/sort-wallets-for-display';
import { WalletHistoryViewType } from '~/entities/wallet/types';
import { MessageType, TokenItemType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import { useCopy } from '~/shared/lib/hooks/use-copy';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const Wallet = memo(function Wallet() {
  const { data: userRes } = useGetUserInfoQuery();
  const { data: walletListRes } = useGetCstmrWalletListQuery();
  const koreanNm = userRes?.tbCstmrMastr?.koreanNm ?? '';
  const dc1TokenAmt = userRes?.tbCstmrMastr?.dc1CoinAmt ?? 0;
  const { aliasNm, priAliasNm } = userRes?.tbCstmrMastr ?? {};

  const myBankCode = appConfig.BANK_CODE ?? '';
  const { shortBankName: myBankName } = useComBankInfo(myBankCode);
  const { copyWalletAddress } = useCopy();
  const { navigate } = useNavigate();

  const isHideBalance = useStore((state) => state.appConfigSlice.isHideBalance);
  const setIsHideBalance = useStore((state) => state.appConfigSlice.setIsHideBalance);
  const toggleHideBalance = () => setIsHideBalance((prev) => !prev);

  const { data: list } = useNotificationListInfiniteQuery({
    paging: { currentPageNo: 1, recordCountPerPage: 99999999, orderBy: { columnList: [] } },
    search: { mssageTycd: MessageType.전체 },
  });

  const hasUnreadNotifications = list?.pages.some((page) =>
    page.result.list.some((notification) => !notification.isRead),
  );

  const stop = useCallback((e: MouseEvent) => e.stopPropagation(), []);

  const walletList = useMemo(
    () => sortWalletsForDisplay(walletListRes || [], { priority: 'primary' }),
    [walletListRes],
  );
  const assetCount = walletList?.length ?? 0;
  const hasWallet = assetCount > 0;

  if (!hasWallet) {
    return (
      <section className="main-wallet-container">
        <div className="main-wallet-card">
          <div className="main-wallet-card-top">
            <div className="main-wallet-title-container row-wrapper">
              <div className="main-wallet-left-wrapper">
                <i className="icon-main-wallet-account" aria-hidden="true"></i>
                <div className="main-wallet-title-wrapper">
                  <div className="main-wallet-title-content">
                    <span className="main-wallet-title">{koreanNm}님 지갑</span>
                  </div>
                </div>
              </div>
            </div>
            <div className="main-wallet-token-container">
              <button
                type="button"
                className="btn-main-wallet-create"
                onClick={() => navigate(PATHS.issueWallet.intro)}
              >
                지갑을 개설해주세요
              </button>
            </div>
          </div>
        </div>
      </section>
    );
  }

  const displayBalance = isHideBalance ? null : dc1TokenAmt.toLocaleString();
  // const walletAccount = `${myBankName} ${priAliasNm ?? aliasNm}`;
  const walletAccount = `${priAliasNm ?? aliasNm}`;

  return (
    <section className="main-wallet-container">
      <div
        className="main-wallet-card"
        onClick={() =>
          navigate(
            `${PATHS.myWallet.history}?coinType=${TokenItemType.DC1}&walletInsttCd=${myBankCode}&coinId=0&aliasNm=${priAliasNm ?? aliasNm}&viewType=${WalletHistoryViewType.TOKEN_HISTORY}`,
          )
        }
      >
        <div className="main-wallet-card-top">
          <div className="main-wallet-title-container row-wrapper">
            <div className="main-wallet-left-wrapper">
              <i className="icon-main-wallet-account" aria-hidden="true"></i>
              <div className="main-wallet-title-wrapper">
                <div className="main-wallet-title-content">
                  <span className="main-wallet-title">{koreanNm}님 지갑</span>
                  <WalletStatus />
                </div>
                <div className="main-wallet-account-wrapper">
                  <p className="main-wallet-account">{walletAccount}</p>
                  <button
                    type="button"
                    className="btn-main-wallet-copy"
                    onClick={(e) => {
                      stop(e);
                      copyWalletAddress();
                    }}
                    aria-label="계좌복사하기"
                  >
                    <i className="icon-main-wallet-copy" aria-hidden="true"></i>
                  </button>
                </div>
              </div>
            </div>
            <div className="main-wallet-right-wrapper">
              <button
                type="button"
                className="btn-main-alarm"
                aria-label="알림진입하기"
                onClick={(e) => {
                  stop(e);
                  navigate(PATHS.notification.list);
                }}
              >
                <i className="icon-main-alarm" aria-hidden="true"></i>
                <i className={`${hasUnreadNotifications ? 'icon-main-alarm-noti' : ''}`} aria-hidden="true"></i>
                {/* {hasUnreadNotifications && <i className="icon-main-alarm-noti" aria-hidden="true"></i>} */}
              </button>
              <button
                type="button"
                className="btn-main-setting"
                aria-label="설정진입하기"
                onClick={(e) => {
                  stop(e);
                  navigate(PATHS.menu);
                }}
              >
                <i className="icon-main-setting" aria-hidden="true"></i>
              </button>
            </div>
          </div>
          <div className={clsx('main-wallet-token-container', isHideBalance && 'is-hidden')}>
            <span className="main-wallet-token-name">예금 토큰</span>
            {isHideBalance ? (
              <>
                <span className="main-wallet-token-hidden-text">잔액 숨김</span>
                <button
                  type="button"
                  className="btn-main-wallet-token-toggle"
                  onClick={(e) => {
                    stop(e);
                    toggleHideBalance();
                  }}
                >
                  보기
                </button>
              </>
            ) : (
              <>
                <span className="main-wallet-token-balance">
                  {displayBalance}
                  <span className="main-wallet-token-won">원</span>
                </span>
                <span
                  className="btn-main-wallet-token-toggle"
                  onClick={(e) => {
                    stop(e);
                    toggleHideBalance();
                  }}
                >
                  숨김
                </span>
              </>
            )}
          </div>
        </div>
        <div className="main-wallet-card-middle">
          <button
            type="button"
            className="btn-main-wallet-convert"
            aria-label="전환진입하기"
            onClick={(e) => {
              stop(e);
              navigate(PATHS.exchange.root);
            }}
          >
            전환
          </button>
          <button
            type="button"
            className="btn-main-wallet-transfer"
            aria-label="송금진입하기"
            onClick={(e) => {
              stop(e);
              navigate(PATHS.exchange.root);
            }}
          >
            송금
          </button>
        </div>
        <div className="main-wallet-card-bottom">
          <button
            type="button"
            className="btn-main-wallet-voucher"
            aria-label="내바우처진입하기"
            onClick={(e) => {
              stop(e);
              navigate(PATHS.voucher.list);
            }}
          >
            <span className="main-wallet-link-voucher">내 바우처 바로가기</span>
            <i className="icon-main-wallet-arrow"></i>
          </button>
        </div>
      </div>
    </section>
  );
});
