import { useEffect } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { useUpdateUserInfo } from '~/entities/user/lib/use-update-user-info';
import { NativeFunction } from '~/shared/constants/native-function';

export const useNotificationRegister = () => {
  const { updateUserInfo } = useUpdateUserInfo();
  const [hasPushTokenSent, setHasPushTokenSent] = useStore(
    useShallow((state) => [state.appConfigSlice.hasPushTokenSent, state.appConfigSlice.setHasPushTokenSent]),
  );

  useEffect(() => {
    // 앱이 아닌 경우 실행하지 않음
    if (!window.ReactNativeWebView) {
      return;
    }
    // 처음 앱 실행시 푸시 토큰 보내기 이후엔 실행하지 않음
    // userInfo?.pushToken로 체크하지 않는 이유는 삭제 후 다시 설치시에는 이미 푸시토큰이 있어서 새로 푸시토큰을 보내지 않기 때문
    if (hasPushTokenSent) {
      return;
    }
    window.webViewBridge.send(NativeFunction.GetNotificationToken, {
      success: (res: any) => {
        const notificationToken = res?.data;
        //서버에 토큰 전송
        updateUserInfo({ pushToken: notificationToken });
        setHasPushTokenSent(true);
      },
    });
  }, []);
};
