import { useEffect } from 'react';
import { useCookies } from 'react-cookie';
import { BlockedWalletDialog } from '~/entities/home/ui/blocked-wallet-dialog';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { WALLET_BLOCK_POPUP_HIDE_TODAY } from '~/shared/constants/cookie';
import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const useShowBlockedWallet = () => {
  const [cookies] = useCookies([WALLET_BLOCK_POPUP_HIDE_TODAY]);
  const { data: userRes } = useGetUserInfoQuery();
  const isWalletBlocked = userRes?.tbCstmrMastr?.isWalletBlocked;

  useEffect(() => {
    if (isWalletBlocked && !cookies.WALLET_BLOCK_POPUP_HIDE_TODAY) {
      overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
        return (
          <Dialog afterLeave={unmount} open={isOpen} onClose={close} buttonLabel={[]}>
            <BlockedWalletDialog />
          </Dialog>
        );
      });
    }
  }, [isWalletBlocked]);
};
